create table if not exists public.caleris_xp_reward_settings(source_type text primary key check(source_type in('race_result','checkin','quest','shop_purchase')),reward_xp integer not null default 0 check(reward_xp>=0),updated_by uuid references auth.users(id),updated_at timestamptz not null default now());
insert into public.caleris_xp_reward_settings(source_type,reward_xp) values('race_result',0),('checkin',0),('quest',0),('shop_purchase',0) on conflict(source_type) do nothing;
alter table public.caleris_xp_reward_settings enable row level security;
create policy "cp xp reward settings admin read" on public.caleris_xp_reward_settings for select to authenticated using(exists(select 1 from public.site_admins where user_id=auth.uid()));
grant select on public.caleris_xp_reward_settings to authenticated;
create or replace function public.caleris_award_configured_xp(p_member uuid,p_source text,p_id text,p_description text) returns void language plpgsql security definer set search_path=public as $$declare n integer;begin select reward_xp into n from public.caleris_xp_reward_settings where source_type=p_source;if coalesce(n,0)>0 then perform public.caleris_award_xp(p_member,n,p_source,p_id,p_description);end if;end$$;
create or replace function public.caleris_xp_race_entry_trigger() returns trigger language plpgsql security definer set search_path=public as $$begin if new.member_id is not null then perform public.caleris_award_configured_xp(new.member_id,'race_result',new.id::text,'Race result participation');end if;return new;end$$;
create or replace function public.caleris_xp_checkin_trigger() returns trigger language plpgsql security definer set search_path=public as $$begin perform public.caleris_award_configured_xp(new.member_id,'checkin',new.id::text,'Race attendance check-in');return new;end$$;
create or replace function public.caleris_xp_quest_trigger() returns trigger language plpgsql security definer set search_path=public as $$begin if new.completed_at is not null and (old.completed_at is null or old.completed_at is distinct from new.completed_at) and new.member_id is not null then perform public.caleris_award_configured_xp(new.member_id,'quest',new.id::text,'Quest completed');end if;return new;end$$;
create or replace function public.caleris_xp_shop_trigger() returns trigger language plpgsql security definer set search_path=public as $$begin if new.member_id is not null then perform public.caleris_award_configured_xp(new.member_id,'shop_purchase',new.id::text,'Development shop purchase');end if;return new;end$$;
drop trigger if exists caleris_xp_race_entry_award on public.caleris_race_result_entries;
create trigger caleris_xp_race_entry_award after insert on public.caleris_race_result_entries for each row execute function public.caleris_xp_race_entry_trigger();
drop trigger if exists caleris_xp_checkin_award on public.license_daily_checkins;
create trigger caleris_xp_checkin_award after insert on public.license_daily_checkins for each row execute function public.caleris_xp_checkin_trigger();
drop trigger if exists caleris_xp_quest_award on public.caleris_quest_assignments;
create trigger caleris_xp_quest_award after update of completed_at on public.caleris_quest_assignments for each row execute function public.caleris_xp_quest_trigger();
drop trigger if exists caleris_xp_shop_award on public.caleris_development_shop_purchases;
create trigger caleris_xp_shop_award after insert on public.caleris_development_shop_purchases for each row execute function public.caleris_xp_shop_trigger();
create or replace function public.caleris_admin_create_poll(p_title text,p_description text,p_type text,p_ends_at timestamptz,p_options jsonb,p_season_id uuid default null) returns uuid language plpgsql security definer set search_path=public as $$declare pid uuid;item jsonb;begin if not exists(select 1 from public.site_admins where user_id=auth.uid()) then raise exception 'not_authorized';end if;if jsonb_typeof(p_options)<>'array' or jsonb_array_length(p_options)<2 then raise exception 'at_least_two_options_required';end if;insert into public.caleris_community_polls(title,description,poll_type,status,starts_at,ends_at,season_id,created_by) values(left(trim(p_title),160),left(coalesce(p_description,''),1000),p_type,'open',now(),p_ends_at,p_season_id,auth.uid()) returning id into pid;for item in select * from jsonb_array_elements(p_options) loop insert into public.caleris_community_poll_options(poll_id,member_id,team_id,label) values(pid,nullif(item->>'member_id','')::uuid,nullif(item->>'team_id','')::uuid,left(coalesce(item->>'label','Candidate'),120));end loop;return pid;end$$;
grant execute on function public.caleris_admin_create_poll(text,text,text,timestamptz,jsonb,uuid) to authenticated;
create or replace function public.caleris_save_yearbook(p_season uuid,p_title text,p_content jsonb) returns void language plpgsql security definer set search_path=public as $$begin if public.caleris_current_member_id() is null then raise exception 'member_profile_required';end if;insert into public.caleris_season_yearbooks(season_id,title,content,status,generated_by) values(p_season,left(p_title,160),p_content,'draft',auth.uid()) on conflict(season_id) do update set title=excluded.title,content=excluded.content,status='draft',generated_at=now(),generated_by=auth.uid();end$$;
grant execute on function public.caleris_save_yearbook(uuid,text,jsonb) to authenticated;
drop policy if exists "cp votes read" on public.caleris_community_votes;
create policy "cp votes own read" on public.caleris_community_votes for select to authenticated using(voter_member_id=public.caleris_current_member_id());
